<?php
declare(strict_types=1);require_once __DIR__.'/../../config/auth.php';require_login('ADMIN');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$q=$pdo->prepare("SELECT * FROM usuarios WHERE id=? AND perfil='ASSOCIADO'");$q->execute([$id]);$u=$q->fetch();if(!$u){http_response_code(404);exit('Associado não encontrado.');}$payload=base64_encode($u['id'].':'.hash_hmac('sha256',(string)$u['id'],qr_secret()));$qr=app_url('api/validar_qr.php?t='.rawurlencode($payload));?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Carteirinha · <?=e($u['nome'])?></title><script src="https://cdn.tailwindcss.com"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><style>@media print{body{background:#fff!important}.no-print{display:none!important}.card{box-shadow:none!important}}</style></head><body class="grid min-h-screen place-items-center bg-slate-100 p-5"><div><div class="card w-full max-w-md overflow-hidden rounded-3xl bg-slate-900 text-white shadow-2xl"><div class="flex items-center justify-between bg-blue-600 px-6 py-5"><b class="text-xl tracking-wide">NEXUS</b><span class="text-xs font-bold">CARTEIRINHA DIGITAL</span></div><div class="p-6"><div class="flex items-center gap-4"><div class="grid h-16 w-16 place-items-center overflow-hidden rounded-2xl bg-blue-100 text-2xl font-bold text-blue-700"><?php if(!empty($u['foto'])):?><img src="<?=e(app_url('uploads/associados/'.$u['foto']))?>" class="h-full w-full object-cover"><?php else:?><?=e(strtoupper(substr($u['nome'],0,1)))?><?php endif;?></div><div><h1 class="text-xl font-bold"><?=e($u['nome'])?></h1><p class="text-sm text-slate-400"><?=e($u['matricula'])?></p></div></div><div class="mt-7 grid grid-cols-2 gap-4 text-sm"><div><small class="text-slate-400">E-mail</small><p class="mt-1 break-all font-semibold"><?=e($u['email'])?></p></div><div><small class="text-slate-400">Telefone</small><p class="mt-1 font-semibold"><?=e($u['telefone']??'Não informado')?></p></div></div><div class="mt-7 flex items-center justify-between rounded-2xl bg-white p-4"><div id="qrcode"></div><div class="text-right text-slate-900"><p class="text-xs font-bold uppercase">Status</p><b class="text-emerald-600"><?=e($u['status_financeiro'])?></b><p class="mt-3 text-[10px] text-slate-500">Apresente este código para validação</p></div></div></div></div><div class="no-print mt-5 flex justify-center gap-3"><button onclick="window.print()" class="rounded-lg bg-slate-900 px-5 py-3 text-sm font-bold text-white">Baixar / imprimir card</button><a href="<?=e(app_url('admin/perfil.php?id='.$id))?>" class="rounded-lg border bg-white px-5 py-3 text-sm font-semibold">Voltar</a></div></div><script>new QRCode(document.getElementById('qrcode'),{text:<?=json_encode($qr)?>,width:125,height:125,colorDark:'#0f172a',colorLight:'#ffffff'});</script></body></html>